use Bike;


-- answer question
-- Q1: Which product has the most online order and been approved? What is the total value sold? 

SELECT
    T.Product_ID,
    SUM(CAST(T.Revenue AS DECIMAL(10, 2))) AS Total_value_sold
FROM
    TransactionDim T
LEFT JOIN
    CurrentCustDim C ON C.CurrentCustDim_ID = T.Customer_ID
WHERE
    T.online_order = 'True'
    AND T.order_status = 'Approved'
GROUP BY
    T.Product_ID
ORDER BY
    Total_value_sold DESC;


-- Q2: What is the total revenue generated by each bicycle brand, and how does it differ in each month?
Select DISTINCT(Brand) From TransactionDim;

SELECT
    MONTH(transaction_date) AS month,
    brand,
    SUM(TransactionDim_ID) OVER (PARTITION BY Brand ORDER BY MONTH(transaction_date)) AS total_revenue
FROM
    TransactionDim
WHERE
    YEAR(transaction_date) = 2023
ORDER BY
    brand, month;

-- Use a differnt approach to solve this question!
Select DISTINCT(Brand) From TransactionDim;

SELECT
    month,
    COALESCE(SUM(CASE WHEN Brand = 'Giant Bicycles' THEN total_revenue END), 0) AS Giant_Bicycles,
    COALESCE(SUM(CASE WHEN Brand = 'Norco Bicycles' THEN total_revenue END), 0) AS Norco_Bicycles,
    COALESCE(SUM(CASE WHEN Brand = 'WeareA2B' THEN total_revenue END), 0) AS WeareA2B,
    COALESCE(SUM(CASE WHEN Brand = 'Trek Bicycles' THEN total_revenue END), 0) AS Trek_Bicycles,
    COALESCE(SUM(CASE WHEN Brand = 'Solex' THEN total_revenue END), 0) AS Solex,
    COALESCE(SUM(CASE WHEN Brand = 'OHM Cycles' THEN total_revenue END), 0) AS OHM_Cycles
FROM (
    SELECT
        MONTH(transaction_date) AS month,
        Brand,
        SUM(Revenue) AS total_revenue
    FROM
        TransactionDim
    WHERE
        YEAR(transaction_date) = 2023
    GROUP BY
        Brand, MONTH(transaction_date)
) AS monthly_revenue
GROUP BY
    month
ORDER BY
    month;